-- 单元测试用 H2 建表，字段与 V100__event_outbox_inbox.sql 的 MySQL 定义一一对应；
-- H2 不支持 ON UPDATE CURRENT_TIMESTAMP，update_time 仅保留默认值（由应用层/触发器之外的方式维护），
-- 与库存 Starter 的测试 DDL 处理一致。
CREATE TABLE IF NOT EXISTS "event_outbox" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "event_id" varchar(64) NOT NULL,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "aggregate_type" varchar(64) NOT NULL,
    "aggregate_id" varchar(64) NOT NULL,
    "event_type" varchar(128) NOT NULL,
    "schema_version" varchar(16) NOT NULL DEFAULT 'v1',
    "partition_key" varchar(128) NOT NULL DEFAULT '',
    "payload" LONGTEXT NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'NEW',
    "retry_count" int NOT NULL DEFAULT 0,
    "next_retry_at" timestamp DEFAULT NULL,
    "occurred_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "published_at" timestamp DEFAULT NULL,
    "trace_id" varchar(64) DEFAULT NULL,
    "last_error" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE KEY "uk_event_id" ("event_id")
);

CREATE TABLE IF NOT EXISTS "event_inbox" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "consumer_name" varchar(64) NOT NULL,
    "event_id" varchar(64) NOT NULL,
    "event_type" varchar(128) NOT NULL DEFAULT '',
    "status" varchar(16) NOT NULL DEFAULT 'RECEIVED',
    "retry_count" int NOT NULL DEFAULT 0,
    "received_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "processed_at" timestamp DEFAULT NULL,
    "error" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE KEY "uk_consumer_event" ("consumer_name", "event_id")
);